module bfs_validator #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 8,\n    parameter MAX_CYCLES = 100\n)(\n    input clk,\n    input rst_n,\n    input start,\n    \n    // Adjacency: each input is an 8-bit bitmask of neighbors for that node\n    input [DATA_WIDTH-1:0] adj_0,\n    input [DATA_WIDTH-1:0] adj_1,\n    input [DATA_WIDTH-1:0] adj_2,\n    input [DATA_WIDTH-1:0] adj_3,\n    input [DATA_WIDTH-1:0] adj_4,\n    input [DATA_WIDTH-1:0] adj_5,\n    input [DATA_WIDTH-1:0] adj_6,\n    input [DATA_WIDTH-1:0] adj_7,\n    \n    // Sequence: 8 elements, each 8-bit (but only low 3 bits used for node ID)\n    input [DATA_WIDTH-1:0] seq_0,\n    input [DATA_WIDTH-1:0] seq_1,\n    input [DATA_WIDTH-1:0] seq_2,\n    input [DATA_WIDTH-1:0] seq_3,\n    input [DATA_WIDTH-1:0] seq_4,\n    input [DATA_WIDTH-1:0] seq_5,\n    input [DATA_WIDTH-1:0] seq_6,\n    input [DATA_WIDTH-1:0] seq_7,\n    \n    output reg valid,\n    output reg done\n);\n\n// State definitions\nlocalparam [2:0] IDLE = 3'd0;\nlocalparam [2:0] CHECK_START = 3'd1;\nlocalparam [2:0] GET_NEIGHBORS = 3'd2;\nlocalparam [2:0] VERIFY_CHILDREN = 3'd3;\nlocalparam [2:0] UPDATE_QUEUE = 3'd4;\nlocalparam [2:0] FINISHED = 3'd5;\n\nreg [2:0] state, next_state;\nreg [7:0] queue;           // One-hot encoding for queue\nreg [7:0] visited;         // Bitmask of visited nodes\nreg [2:0] head_ptr;        // Index in sequence for current node\nreg [2:0] child_ptr;       // Index in sequence for children\nreg [2:0] current_node;    // Node being processed\nreg [7:0] neighbor_mask;   // Unvisited neighbors\nreg [2:0] neighbor_count;  // Count of unvisited neighbors\nreg [2:0] verify_count;    // How many children verified\nreg [3:0] cycle_count;     // Timeout counter\n\n// Helper: Get adjacency for current node\nwire [7:0] current_adj;\nassign current_adj = (current_node == 3'd0) ? adj_0 :\n                     (current_node == 3'd1) ? adj_1 :\n                     (current_node == 3'd2) ? adj_2 :\n                     (current_node == 3'd3) ? adj_3 :\n                     (current_node == 3'd4) ? adj_4 :\n                     (current_node == 3'd5) ? adj_5 :\n                     (current_node == 3'd6) ? adj_6 : adj_7;\n\n// Helper: Get sequence element\nwire [7:0] get_seq;\nassign get_seq = (head_ptr == 3'd0) ? seq_0 :\n                 (head_ptr == 3'd1) ? seq_1 :\n                 (head_ptr == 3'd2) ? seq_2 :\n                 (head_ptr == 3'd3) ? seq_3 :\n                 (head_ptr == 3'd4) ? seq_4 :\n                 (head_ptr == 3'd5) ? seq_5 :\n                 (head_ptr == 3'd6) ? seq_6 : seq_7;\n\n// Helper: Get sequence element at child position\nwire [7:0] child_seq;\nassign child_seq = (child_ptr == 3'd0) ? seq_0 :\n                   (child_ptr == 3'd1) ? seq_1 :\n                   (child_ptr == 3'd2) ? seq_2 :\n                   (child_ptr == 3'd3) ? seq_3 :\n                   (child_ptr == 3'd4) ? seq_4 :\n                   (child_ptr == 3'd5) ? seq_5 :\n                   (child_ptr == 3'd6) ? seq_6 : seq_7;\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n    end else begin\n        state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: begin\n            if (start) next_state = CHECK_START;\n        end\n        CHECK_START: begin\n            // Check if first element is 1 (0-indexed)\n            if (get_seq != 8'd0) begin\n                next_state = FINISHED;\n            end else begin\n                next_state = GET_NEIGHBORS;\n            end\n        end\n        GET_NEIGHBORS: begin\n            if (queue == 8'd0) begin\n                next_state = FINISHED;\n            end else begin\n                next_state = VERIFY_CHILDREN;\n            end\n        end\n        VERIFY_CHILDREN: begin\n            if (verify_count >= neighbor_count) begin\n                next_state = UPDATE_QUEUE;\n            end else if (child_ptr >= N || cycle_count >= MAX_CYCLES) begin\n                next_state = FINISHED;\n            end else begin\n                next_state = VERIFY_CHILDREN;\n            end\n        end\n        UPDATE_QUEUE: begin\n            if (head_ptr >= N) begin\n                next_state = FINISHED;\n            end else begin\n                next_state = GET_NEIGHBORS;\n            end\n        end\n        FINISHED: next_state = FINISHED;\n        default: next_state = IDLE;\n    endcase\nend\n\n// Datapath logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        valid <= 1'b0;\n        done <= 1'b0;\n        queue <= 8'd0;\n        visited <= 8'd0;\n        head_ptr <= 3'd0;\n        child_ptr <= 3'd0;\n        current_node <= 3'd0;\n        neighbor_mask <= 8'd0;\n        neighbor_count <= 3'd0;\n        verify_count <= 3'd0;\n        cycle_count <= 4'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                valid <= 1'b0;\n                done <= 1'b0;\n                cycle_count <= 4'd0;\n            end\n            \n            CHECK_START: begin\n                if (get_seq == 8'd0) begin\n                    // Initialize BFS with node 0\n                    queue <= 8'b00000001;\n                    visited <= 8'b00000001;\n                    head_ptr <= 3'd1;\n                    current_node <= 3'd0;\n                    valid <= 1'b1; // Assume valid until proven otherwise\n                end else begin\n                    valid <= 1'b0;\n                    done <= 1'b1;\n                end\n            end\n            \n            GET_NEIGHBORS: begin\n                // Find next node in queue (lowest set bit)\n                integer i;\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (queue[i] && (current_node == 3'd0 || current_node > i)) begin\n                        current_node <= i;\n                    end\n                end\n                \n                // Get neighbors and remove visited\n                neighbor_mask <= current_adj & ~visited;\n                \n                // Count neighbors\n                neighbor_count <= 0;\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (current_adj[i] && !visited[i]) begin\n                        neighbor_count <= neighbor_count + 1;\n                    end\n                end\n                \n                verify_count <= 0;\n                child_ptr <= head_ptr;\n                cycle_count <= cycle_count + 1;\n            end\n            \n            VERIFY_CHILDREN: begin\n                if (verify_count < neighbor_count && child_ptr < N) begin\n                    // Check if child_seq is in neighbor_mask\n                    if (child_seq < 8 && neighbor_mask[child_seq]) begin\n                        verify_count <= verify_count + 1;\n                        child_ptr <= child_ptr + 1;\n                    end else begin\n                        valid <= 1'b0;\n                    end\n                end\n                cycle_count <= cycle_count + 1;\n            end\n            \n            UPDATE_QUEUE: begin\n                // Enqueue all verified children\n                integer i;\n                for (i = 0; i < 8; i = i + 1) begin\n                    if (neighbor_mask[i]) begin\n                        queue[i] <= 1'b1;\n                        visited[i] <= 1'b1;\n                    end\n                end\n                \n                // Remove current node from queue\n                queue[current_node] <= 1'b0;\n                \n                // Update head pointer\n                head_ptr <= head_ptr + neighbor_count;\n                \n                // Check if we're done\n                if (head_ptr + neighbor_count >= N) begin\n                    done <= 1'b1;\n                end\n            end\n            \n            FINISHED: begin\n                done <= 1'b1;\n                if (!valid) valid <= 1'b0;\n            end\n        endcase\n    end\nend\n\nendmodule